-- PT118-S3-Q21. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT118-S3-Q21$batch12$ AND q.stimulus=$batch12$Experimental psychology requires the application of statistics to interpret empirical data and assess their significance. A person will not be able to understand such applications without training in statistics. Therefore, the more training one has in statistics, the better one will be at research in experimental psychology.$batch12$ AND q.prompt=$batch12$Which one of the following arguments exhibits a flawed pattern of reasoning most similar to that exhibited by the argument above?$batch12$ AND q.correct_choice=$batch12$A$batch12$) THEN RAISE EXCEPTION 'Question changed: PT118-S3-Q21'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT118-S3-Q21$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S3-Q21'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT118-S3-Q21$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The more statistics training, the better at experimental psychology research.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Experimental psychology requires statistics, and you can't understand those applications without training.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The evidence says training is required. The conclusion says more training keeps making you better. A requirement doesn't mean more is always better.$batch12$), (3, $batch12$Goal$batch12$, $batch12$X is required for Y, so more X means more Y.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT118-S3-Q21$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$People need love and support to avoid unhappiness, so the more love, the happier. Same jump from requirement to "more is better."$batch12$), ($batch12$B$batch12$, $batch12$Annual raises do mean longer service brings more income. Reasonable.$batch12$), ($batch12$C$batch12$, $batch12$This is a causal claim about a condition building over time.$batch12$), ($batch12$D$batch12$, $batch12$This restates a requirement as a requirement. It never says more is better.$batch12$), ($batch12$E$batch12$, $batch12$This treats chemistry as nearly enough for medicine, a sufficiency flaw.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT118-S3-Q21$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
